/* Grade 8 multiple-choice tests: 3 per subject, 40 questions, 30 minutes, Terms 3 and 4 mixed.
   Uses M, placeMC and MC_INTRO from tests-g7.js. */

/* Split question pools into 3 tests: every third question goes to each test, so every test covers every topic;
   with two pools (Term 3 and Term 4) the questions alternate between the terms. */
function defineSets(prefix, grade, subject, name, what, A, B, shift){
  for(let t=0;t<3;t++){
    const a = A.filter((_,i)=>i%3===t), b = B ? B.filter((_,i)=>i%3===t) : [];
    const items = []; for(let i=0;i<Math.max(a.length,b.length);i++){ if(a[i]) items.push(a[i]); if(b[i]) items.push(b[i]); }
    defineTest(`${prefix}-t${t+1}`, {grade, subject, kind:"mc", minutes:30,
      title:`${name} Test ${t+1} · Multiple choice${B?" · Terms 3 and 4":""}`, intro:MC_INTRO(what), mc:placeMC(items, shift + t*7)});
  }
}

